<?php require_once __DIR__.'/../core.php'; require_once __DIR__.'/auth.php'; ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Campagnes</title><link rel="stylesheet" href="/assets/css/style.css?v=110"></head><body><div class="admin-layout"><?php include __DIR__.'/sidebar.php'; ?><main class="admin-main"><?php $items=data_list('campaigns');$prospects=data_list('prospects'); if($_SERVER['REQUEST_METHOD']==='POST'){campaign_prepare($_POST['title'],$_POST['sender'],$_POST['channels']??[],$_POST['message']);header('Location:/admin/campaigns.php');exit;} ?><h1>Campagnes SMS / Email / WhatsApp</h1><form class="card" method="post"><div class="form-grid"><label>Titre<input name="title"></label><label>Sender name<input name="sender" value="GEA-H"></label><label>Canaux<div><label><input type="checkbox" name="channels[]" value="sms"> SMS</label><label><input type="checkbox" name="channels[]" value="email"> Email</label><label><input type="checkbox" name="channels[]" value="whatsapp"> WhatsApp</label></div></label><label class="full">Message<textarea name="message"></textarea></label></div><button class="btn btn-primary">Préparer campagne</button></form><table class="table"><tr><th>Date</th><th>Titre</th><th>Canaux</th><th>Sender</th><th>Prospects</th><th>Statut</th></tr><?php foreach(array_reverse($items) as $c): ?><tr><td><?=e($c['date'])?></td><td><?=e($c['title'])?></td><td><?=e(implode(', ',$c['channels']))?></td><td><?=e($c['sender'])?></td><td><?=e($c['count'])?></td><td><?=e($c['status'])?></td></tr><?php endforeach; ?></table></main></div><script>
(function(){const saved=localStorage.getItem('geah_theme')||'dark';if(saved==='light')document.body.classList.add('light-mode');function ready(){const btn=document.createElement('button');btn.className='theme-toggle';function label(){btn.textContent=document.body.classList.contains('light-mode')?'🌙 Mode sombre':'☀️ Mode clair'}btn.onclick=function(){document.body.classList.toggle('light-mode');localStorage.setItem('geah_theme',document.body.classList.contains('light-mode')?'light':'dark');label()};label();document.body.appendChild(btn)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ready);else ready();})();
</script></body></html>